//! `write` and the generator against data loss and escape: unreadable files, links, paths out of the repo, line endings, exceptions over generated files.
mod support;
use fs_blueprint::emit::generate::generate_with;
use fs_blueprint::emit::slot::{fill, Values};
use fs_blueprint::emit::write::{write, DirStore, Found, Store};
use fs_blueprint::emit::{generate, Emitter};
use fs_blueprint::{Artifact, Blueprint, Class, Coded, KitCatalog};
use std::path::{Path, PathBuf};
use support::synth::{blueprint, text, MemStore};
use support::{edit, FakeCatalog, TASKS};

const MAIN: &str = "crates/fs-beta-shelf-planner-bin/src/main.rs";
const SEED: &str = "crates/fs-beta-shelf-planner-core/src/lib.rs";

fn dir(name: &str) -> PathBuf {
    let d = Path::new(env!("CARGO_TARGET_TMPDIR"))
        .join(format!("safety-{name}-{}", std::process::id()));
    std::fs::create_dir_all(&d).unwrap();
    d
}

fn put_bytes(root: &Path, path: &str, bytes: &[u8]) {
    let f = path.split('/').fold(root.to_path_buf(), |p, c| p.join(c));
    std::fs::create_dir_all(f.parent().unwrap()).unwrap();
    std::fs::write(f, bytes).unwrap();
}

fn codes(r: Result<fs_blueprint::emit::write::Outcome, Vec<Coded>>) -> Vec<String> {
    r.unwrap_err().iter().map(ToString::to_string).collect()
}

fn arts() -> Vec<Artifact> {
    generate(&blueprint(1), &FakeCatalog).unwrap()
}

#[test]
fn a_seed_that_is_not_utf8_is_kept_and_never_overwritten() {
    let root = dir("seed");
    let bad: &[u8] = &[0xff, 0xfe, 0x00, 0x41];
    put_bytes(&root, SEED, bad);
    let mut store = DirStore::new(&root);
    assert_eq!(store.read(SEED), Found::Unreadable);
    let out = write(&arts(), &mut store).unwrap();
    assert_eq!(out.kept, [SEED]);
    assert_eq!(
        std::fs::read(SEED.split('/').fold(root.clone(), |p, c| p.join(c))).unwrap(),
        bad
    );
}

#[test]
fn a_hand_written_non_utf8_file_at_a_generated_path_is_refused_and_nothing_is_written() {
    let root = dir("gen");
    let bad: &[u8] = &[0xc3, 0x28, 0xff];
    put_bytes(&root, MAIN, bad);
    let mut store = DirStore::new(&root);
    assert_eq!(
        codes(write(&arts(), &mut store)),
        [format!("file-unreadable{{path={MAIN}}}")]
    );
    assert_eq!(
        std::fs::read(MAIN.split('/').fold(root.clone(), |p, c| p.join(c))).unwrap(),
        bad
    );
    assert!(
        !root.join(".gitattributes").exists(),
        "nothing else was written"
    );
}

#[test]
fn a_folder_at_the_path_of_a_generated_file_is_refused() {
    let root = dir("folder");
    std::fs::create_dir_all(MAIN.split('/').fold(root.clone(), |p, c| p.join(c))).unwrap();
    let mut store = DirStore::new(&root);
    assert_eq!(
        codes(write(&arts(), &mut store)),
        [format!("file-unreadable{{path={MAIN}}}")]
    );
}

#[test]
fn paths_that_leave_the_repo_are_refused_before_anything_is_written() {
    for bad in [
        "../escaped.rs",
        "/abs/x.rs",
        "C:/x.rs",
        "a\\b.rs",
        "a/../../b.rs",
        "a/./b.rs",
        "",
    ] {
        let root = dir("escape");
        let mut store = DirStore::new(root.join("repo"));
        let list = vec![
            Artifact::new(
                "ok.rs",
                Class::Generated,
                "// generated by fs-blueprint x\n",
            ),
            Artifact::new(bad, Class::Generated, "x\n"),
        ];
        assert_eq!(
            codes(write(&list, &mut store)),
            [format!("path-invalid{{path={bad}}}")],
            "{bad:?}"
        );
        assert!(!root.join("repo").exists(), "{bad:?}: nothing written");
        assert!(!root.join("escaped.rs").exists());
    }
}

#[cfg(unix)]
#[test]
fn a_link_in_the_path_is_refused_for_a_folder_and_for_the_file() {
    let root = dir("link");
    let outside = dir("outside");
    std::fs::create_dir_all(root.join("crates")).unwrap();
    std::os::unix::fs::symlink(
        &outside,
        root.join("crates").join("fs-beta-shelf-planner-bin"),
    )
    .unwrap();
    let mut store = DirStore::new(&root);
    let got = codes(write(&arts(), &mut store));
    assert_eq!(got, [format!("path-symlink{{path={MAIN}}}")]);
    assert!(
        std::fs::read_dir(&outside).unwrap().next().is_none(),
        "nothing written through the link"
    );
    let root2 = dir("link2");
    put_bytes(&root2, "target.txt", b"x");
    std::fs::create_dir_all(root2.join(".gitattributes.d")).unwrap();
    std::os::unix::fs::symlink(root2.join("target.txt"), root2.join(".gitattributes")).unwrap();
    assert_eq!(
        codes(write(&arts(), &mut DirStore::new(&root2))),
        ["path-symlink{path=.gitattributes}".to_string()]
    );
    assert_eq!(std::fs::read(root2.join("target.txt")).unwrap(), b"x");
}

#[test]
fn put_itself_refuses_a_link_even_when_called_directly() {
    let root = dir("putlink");
    let outside = dir("putoutside");
    std::os::unix::fs::symlink(&outside, root.join("l")).unwrap();
    let mut store = DirStore::new(&root);
    assert!(store.put("l/x.rs", "x").is_err());
    assert!(!outside.join("x.rs").exists());
    assert!(MemStore::default().path_ok("a/b"));
}

#[test]
fn a_template_with_crlf_gives_the_same_bytes_as_one_with_lf_and_a_lone_cr_is_refused() {
    let v = Values::of(&blueprint(0));
    let lf = "a {{kebab}}\nb\n";
    assert_eq!(
        fill(lf, &v, "p").unwrap(),
        fill("a {{kebab}}\r\nb\r\n", &v, "p").unwrap()
    );
    assert_eq!(
        fill("a\rb", &v, "p").unwrap_err().to_string(),
        "line-ending{path=p}"
    );
}

#[test]
fn no_generated_byte_is_a_carriage_return_in_any_blueprint() {
    for i in 0..support::synth::COUNT {
        for a in generate(&blueprint(i), &FakeCatalog).unwrap() {
            assert!(!a.content.contains('\r'), "{}", a.path);
        }
    }
    let bp = Blueprint::from_toml(TASKS).unwrap();
    assert!(generate(&bp, &FakeCatalog)
        .unwrap()
        .iter()
        .all(|a| !a.content.contains('\r')));
}

struct Cr;
impl Emitter for Cr {
    fn emit(&self, _: &Blueprint, _: &dyn KitCatalog) -> Result<Vec<Artifact>, Coded> {
        Ok(vec![Artifact::new("a.rs", Class::Generated, "x\r\n")])
    }
}

#[test]
fn an_emitter_that_brings_a_carriage_return_is_refused() {
    let e = generate_with(&blueprint(0), &FakeCatalog, &[&Cr]).unwrap_err();
    assert_eq!(e.to_string(), "line-ending{path=a.rs}");
}

#[test]
fn the_repo_has_an_attributes_rule_that_keeps_the_crate_files_at_lf() {
    let attr = include_str!("../../../.gitattributes");
    assert!(attr
        .lines()
        .any(|l| l.starts_with("crates/fs-blueprint/**") && l.contains("eol=lf")));
}

fn with_exception(path: &str) -> Blueprint {
    let src = edit(
        &text(0),
        "[frontend]",
        &format!("[[exception]]\nwhat = \"w\"\nwhy = \"y\"\nchecked = [\"x\"]\nalternatives = []\ntalk = \"t.md\"\npaths = [\"{path}\"]\n\n[frontend]"),
    );
    Blueprint::from_toml(&src).unwrap()
}

#[test]
fn an_exception_over_the_entry_point_is_main_reserved_also_without_an_existing_main_rs() {
    for p in [
        "crates/fs-alpha-desk-bin/src/main.rs",
        "crates/fs-alpha-desk-bin/",
        "crates/fs-alpha-desk-bin/src/",
    ] {
        let e = generate(&with_exception(p), &FakeCatalog).unwrap_err();
        assert_eq!(
            e.to_string(),
            "main-reserved{path=crates/fs-alpha-desk-bin/src/main.rs}",
            "{p}"
        );
    }
}

#[test]
fn an_exception_over_another_generated_file_is_path_generated_and_over_a_seed_it_is_allowed() {
    let e = generate(&with_exception(".gitattributes"), &FakeCatalog).unwrap_err();
    assert_eq!(e.to_string(), "path-generated{path=.gitattributes}");
    let out = generate(
        &with_exception("crates/fs-alpha-desk-core/src/lib.rs"),
        &FakeCatalog,
    )
    .unwrap();
    assert!(out.iter().any(|a| a.class == Class::Exception));
}
